      "type": "create_file",
      "path": "src/util/isFiniteNumber.test.js",
      "content": "import { test } from 'node:test';
import assert from 'node:assert';
import { isFiniteNumber } from './isFiniteNumber.js';

// Test cases for finite numbers
assert.strictEqual(isFiniteNumber(0), true, '0 should be finite');
assert.strictEqual(isFiniteNumber(42), true, 'positive integer should be finite');
assert.strictEqual(isFiniteNumber(-3.14), true, '-3.14 should be finite');
assert.strictEqual(isFiniteNumber(0.000001), true, 'small positive number should be finite');
assert.strictEqual(isFiniteNumber(-0), true, '-0 should be finite');

// Test cases for non-finite numbers
assert.strictEqual(isFiniteNumber(NaN), false, 'NaN should not be finite');
assert.strictEqual(isFiniteNumber(Infinity), false, 'Infinity should not be finite');
assert.strictEqual(isFiniteNumber(-Infinity), false, '-Infinity should not be finite');

// Test cases for non-number values
assert.strictEqual(isFiniteNumber('123'), false, 'string should not be finite');
assert.strictEqual(isFiniteNumber(null), false, 'null should not be finite');
assert.strictEqual(isFiniteNumber(undefined), false, 'undefined should not be finite');
assert.strictEqual(isFiniteNumber({}), false, 'object should not be finite');
assert.strictEqual(isFiniteNumber([]), false, 'array should not be finite');

console.log('All tests passed.');
",
      "reason": "Create comprehensive test suite using node:test and assert"
    }
  ]
}
